import React, { useEffect, useRef, useState } from 'react';

function EventCard({ title, date, time, location, delay, visible }) {
  const addToCalendar = () => {
    const start = title === 'Akad Nikah' ? '20240127T090000' : '20240128T090000';
    const end = title === 'Akad Nikah' ? '20240127T120000' : '20240128T120000';
    const url = `https://calendar.google.com/calendar/render?action=TEMPLATE&text=Wedding+Nobita+%26+Shizuka+-+${encodeURIComponent(title)}&dates=${start}/${end}&details=Pernikahan+Nobita+%26+Shizuka&location=${encodeURIComponent(location)}`;
    window.open(url, '_blank');
  };

  return (
    <div
      style={{
        background: 'white',
        borderRadius: '16px',
        padding: '36px 30px',
        flex: 1,
        minWidth: '280px',
        maxWidth: '380px',
        boxShadow: '0 4px 20px rgba(0,0,0,0.08)',
        border: '1px solid #f0e0ec',
        opacity: 0,
        animation: visible ? `fadeUp 0.7s ease ${delay}s forwards` : 'none',
      }}
    >
      <h3 style={{
        fontFamily: "'Poppins', sans-serif",
        fontSize: '1.3rem',
        fontWeight: 600,
        color: '#333',
        marginBottom: '20px',
        paddingBottom: '16px',
        borderBottom: '1px solid #f0e0ec',
      }}>
        {title}
      </h3>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', marginBottom: '28px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <span style={{ fontSize: '1.1rem' }}>📅</span>
          <span style={{ fontFamily: "'Poppins', sans-serif", fontSize: '0.95rem', color: '#555' }}>{date}</span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <span style={{ fontSize: '1.1rem' }}>🕘</span>
          <span style={{ fontFamily: "'Poppins', sans-serif", fontSize: '0.95rem', color: '#555' }}>{time}</span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <span style={{ fontSize: '1.1rem' }}>📍</span>
          <span style={{ fontFamily: "'Poppins', sans-serif", fontSize: '0.95rem', color: '#555' }}>{location}</span>
        </div>
      </div>

      <button
        onClick={addToCalendar}
        style={{
          width: '100%',
          background: '#e91e8c',
          color: 'white',
          border: 'none',
          borderRadius: '50px',
          padding: '14px 20px',
          fontSize: '0.85rem',
          fontWeight: 600,
          fontFamily: "'Poppins', sans-serif",
          cursor: 'pointer',
          letterSpacing: '0.08em',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          gap: '8px',
          transition: 'all 0.2s',
        }}
        onMouseEnter={e => { e.currentTarget.style.background = '#c91578'; e.currentTarget.style.transform = 'translateY(-2px)'; }}
        onMouseLeave={e => { e.currentTarget.style.background = '#e91e8c'; e.currentTarget.style.transform = 'translateY(0)'; }}
      >
        📅 SIMPAN KE KALENDER
      </button>
    </div>
  );
}

export default function EventSection() {
  const [visible, setVisible] = useState(false);
  const ref = useRef();

  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => {
      if (e.isIntersecting) setVisible(true);
    }, { threshold: 0.2 });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);

  return (
    <section ref={ref} style={{
      background: 'white',
      padding: '80px 20px',
      textAlign: 'center',
    }}>
      <style>{`
        @keyframes fadeUp {
          from { opacity: 0; transform: translateY(30px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>

      {/* Section title */}
      <h2 style={{
        fontFamily: "'Dancing Script', cursive",
        fontSize: 'clamp(2rem, 6vw, 3rem)',
        color: '#e91e8c',
        marginBottom: '20px',
        opacity: visible ? 1 : 0,
        animation: visible ? 'fadeUp 0.7s ease 0.1s forwards' : 'none',
      }}>
        Acara Pernikahan
      </h2>

      <p style={{
        fontFamily: "'Poppins', sans-serif",
        fontSize: 'clamp(0.85rem, 2.5vw, 1rem)',
        color: '#666',
        maxWidth: '700px',
        margin: '0 auto 50px',
        lineHeight: 1.8,
        opacity: visible ? 1 : 0,
        animation: visible ? 'fadeUp 0.7s ease 0.2s forwards' : 'none',
      }}>
        Merupakan suatu kehormatan dan kebahagiaan bagi kami apabila, Bapak/Ibu/Saudara/i
        berkenan hadir untuk memberikan do'a restunya, kami ucapkan terima kasih.
      </p>

      {/* Event cards */}
      <div style={{
        display: 'flex',
        gap: '24px',
        justifyContent: 'center',
        flexWrap: 'wrap',
        maxWidth: '900px',
        margin: '0 auto',
      }}>
        <EventCard
          title="Akad Nikah"
          date="13,"
          time="09:00 WIB - Selesai"
          location="Lokasi di Jakarta"
          delay={0.3}
          visible={visible}
        />
        <EventCard
          title="Resepsi"
          date="Minggu, 28 Januari 2024"
          time="09:00 WIB - Selesai"
          location="Lokasi di Jakarta"
          delay={0.5}
          visible={visible}
        />
      </div>
    </section>
  );
}
